# server.py - Updated with pairing and logout functionality
from flask import Flask, request, jsonify, session, redirect, url_for
from flask_session import Session
import uuid

app = Flask(__name__)
app.secret_key = 'your_secret_key_here'
app.config['SESSION_TYPE'] = 'filesystem'
Session(app)

# In-memory storage for users and rooms
users = {}
rooms = {}

@app.route('/register', methods=['POST'])
def register():
    data = request.json
    username = data.get('username')
    password = data.get('password')

    if username in users:
        return jsonify({'success': False, 'message': 'Username already exists'})

    users[username] = password
    session['username'] = username
    return jsonify({'success': True, 'message': 'Registration successful'})

@app.route('/login', methods=['POST'])
def login():
    data = request.json
    username = data.get('username')
    password = data.get('password')

    if username not in users or users[username] != password:
        return jsonify({'success': False, 'message': 'Invalid credentials'})

    session['username'] = username
    return jsonify({'success': True, 'message': 'Login successful'})

@app.route('/logout', methods=['POST'])
def logout():
    session.pop('username', None)
    return jsonify({'success': True, 'message': 'Logout successful'})

@app.route('/check-auth', methods=['GET'])
def check_auth():
    if 'username' in session:
        return jsonify({'authenticated': True, 'username': session.get('username')})
    else:
        return jsonify({'authenticated': False})

@app.route('/create-room', methods=['POST'])
def create_room():
    room_id = str(uuid.uuid4())
    rooms[room_id] = {
        'players': [session.get('username')],
        'ready': [],
        'gameStarted': False
    }
    return jsonify({'success': True, 'room_id': room_id})

@app.route('/join-room', methods=['POST'])
def join_room():
    room_id = request.json.get('room_id')
    if room_id not in rooms:
        return jsonify({'success': False, 'message': 'Room not found'})

    if len(rooms[room_id]['players']) >= 2:
        return jsonify({'success': False, 'message': 'Room is full'})

    rooms[room_id]['players'].append(session.get('username'))
    return jsonify({'success': True, 'message': 'Joined room successfully'})

@app.route('/random-matchmaking', methods=['POST'])
def random_matchmaking():
    for room_id, room in rooms.items():
        if len(room['players']) == 1 and not room.get('gameStarted', False):
            room['players'].append(session.get('username'))
            return jsonify({'success': True, 'room_id': room_id})

    room_id = str(uuid.uuid4())
    rooms[room_id] = {
        'players': [session.get('username')],
        'ready': [],
        'gameStarted': False
    }
    return jsonify({'success': True, 'room_id': room_id})

@app.route('/start-game/<room_id>', methods=['POST'])
def start_game(room_id):
    if room_id not in rooms:
        return jsonify({'success': False, 'message': 'Room not found'})

    room = rooms[room_id]
    username = session.get('username')

    if username not in room['players']:
        return jsonify({'success': False, 'message': 'You are not in this room'})

    if username not in room['ready']:
        room['ready'].append(username)

    if len(room['ready']) == 2:
        room['gameStarted'] = True
        return jsonify({'success': True, 'game_started': True})

    return jsonify({'success': True, 'game_started': False})

if __name__ == '__main__':
    app.run(debug=True)
